     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nDYNAMIC CLASS CREATION\n========================\n\nPython classes can be created at runtime using:\n  1. type(name, bases, namespace)\n  2. types.new_class()\n  3. Metaclass __new__\n\"\"\"\n\n\ndef demo_dynamic_class():\n    # Method 1: type()\n    Animal = type(\"Animal\", (object,), {\n        \"species\": \"Unknown\",\n        \"__init__\": lambda self, name: setattr(self, \"name\", name),\n        \"speak\": lambda self: f\"{self.name} the {self.species} speaks\",\n        \"__repr__\": lambda self: f\"Animal({self.name!r})\"\n    })\n\n    a = Animal(\"Rex\")\n    print(f\"  Dynamic class: {a.speak()}\")\n\n    # Create subclass dynamically\n    Dog = type(\"Dog\", (Animal,), {\n        \"species\": \"Dog\",\n        \"fetch\": lambda self, item: f\"{self.name} fetches {item}\"\n    })\n\n    d = Dog(\"Buddy\")\n    print(f\"  Dynamic subclass: {d.speak()}, {d.fetch('ball')}\")\n\n    # Method 2: Build class from config\n    def create_model(name, fields):\n        \"\"\"Create a data class dynamically from field definitions.\"\"\"\n        def init(self, **kwargs):\n            for field_name in fields:\n                setattr(self, field_name, kwargs.get(field_name))\n\n        def repr_(self):\n            attrs = \", \".join(f\"{f}={getattr(self, f)!r}\" for f in fields)\n            return f\"{name}({attrs})\"\n\n        return type(name, (object,), {\n            \"__init__\": init,\n            \"__repr__\": repr_,\n            \"_fields\": fields\n        })\n\n    Product = create_model(\"Product\", [\"name\", \"price\", \"quantity\"])\n    p = Product(name=\"Widget\", price=9.99, quantity=100)\n    print(f\"  Config-based: {p}\")\n\n\nprint(\"Q194: Dynamic Class Creation\")\ndemo_dynamic_class()\nprint()",
