     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nFROZEN DATACLASSES\n===================\n\n@dataclass(frozen=True) makes instances immutable.\nGenerates __hash__ automatically (since immutable).\nCan be used as dict keys and set elements.\n\"\"\"\n\n\n@dataclass(frozen=True)\nclass Coordinate:\n    x: float\n    y: float\n\n    @property\n    def distance_from_origin(self):\n        return (self.x ** 2 + self.y ** 2) ** 0.5\n\n\ndef demo_dataclasses():\n    # Regular dataclass\n    p = Product(\"Widget\", 9.99, 5)\n    print(f\"  Product: {p}\")\n    print(f\"  Total value: ${p.total_value:.2f}\")\n    p.price = 12.99  # Mutable\n    print(f\"  After price change: {p}\")\n\n    # Frozen dataclass\n    c1 = Coordinate(3.0, 4.0)\n    c2 = Coordinate(3.0, 4.0)\n    print(f\"\\n  Coordinate: {c1}\")\n    print(f\"  Distance: {c1.distance_from_origin}\")\n    print(f\"  c1 == c2: {c1 == c2}\")\n    print(f\"  Hashable: {hash(c1)}\")\n\n    # Immutable\n    try:\n        c1.x = 5.0\n    except Exception as e:\n        print(f\"  Can't modify frozen: {e}\")\n\n    # Can use as dict key\n    distances = {c1: \"close\", Coordinate(10.0, 10.0): \"far\"}\n    print(f\"  As dict key: {distances[Coordinate(3.0, 4.0)]}\")\n\n\nprint(\"Q195-196: Data Classes & Frozen Dataclasses\")\ndemo_dataclasses()\nprint()",
