     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nREGISTRY PATTERN\n==================\n\nMaintains a global registry of classes/objects that can be looked up\nby name. Common in plugin systems and frameworks.\n\"\"\"\n\n\nclass HandlerRegistry:\n    \"\"\"Central registry for request handlers.\"\"\"\n    _handlers = {}\n\n    @classmethod\n    def register(cls, name):\n        \"\"\"Decorator to register a handler.\"\"\"\n        def decorator(handler_cls):\n            cls._handlers[name] = handler_cls\n            return handler_cls\n        return decorator\n\n    @classmethod\n    def get(cls, name):\n        handler_cls = cls._handlers.get(name)\n        if not handler_cls:\n            raise KeyError(f\"No handler registered for '{name}'\")\n        return handler_cls()\n\n    @classmethod\n    def list_handlers(cls):\n        return list(cls._handlers.keys())\n\n\n@HandlerRegistry.register(\"json\")\nclass JsonHandler:\n    def process(self, data):\n        return f\"Processing JSON: {data}\"\n\n\n@HandlerRegistry.register(\"xml\")\nclass XmlHandler:\n    def process(self, data):\n        return f\"Processing XML: {data}\"\n\n\n@HandlerRegistry.register(\"csv\")\nclass CsvHandler:\n    def process(self, data):\n        return f\"Processing CSV: {data}\"\n\n\ndef demo_registry():\n    print(f\"  Registered handlers: {HandlerRegistry.list_handlers()}\")\n\n    for fmt in [\"json\", \"xml\", \"csv\"]:\n        handler = HandlerRegistry.get(fmt)\n        print(f\"  {handler.process('sample data')}\")\n\n\nprint(\"Q199: Registry Pattern\")\ndemo_registry()\nprint()",
