     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nPYDANTIC MODELS\n================\n\nPydantic provides runtime data validation using Python type annotations.\nIt's the backbone of FastAPI and widely used in production Python.\n\nKey Features:\n  - Automatic type coercion (str \"42\" → int 42)\n  - Validation with detailed error messages\n  - JSON serialization/deserialization\n  - Field validators (custom validation logic)\n  - model_dump(), model_json_schema()\n  - Immutable models (frozen=True)\n  - Nested models\n  - Discriminated unions\n\nPydantic v2 (current):\n  - Built on pydantic-core (Rust-based) — 5-50x faster than v1\n  - model_validate(), model_dump() instead of parse_obj(), dict()\n\nNOTE: This demo uses a simplified version since pydantic may not be installed.\n\"\"\"\n\n\n# Simplified Pydantic-like model for demonstration\nclass PydanticLikeModel:\n    \"\"\"Simplified model showing pydantic concepts.\"\"\"\n\n    def __init_subclass__(cls, **kwargs):\n        super().__init_subclass__(**kwargs)\n        cls._fields = {}\n        for name, annotation in getattr(cls, '__annotations__', {}).items():\n            cls._fields[name] = annotation\n\n    def __init__(self, **kwargs):\n        for name, type_ in self._fields.items():\n            value = kwargs.get(name)\n            if value is None and not hasattr(self, name):\n                raise ValueError(f\"Field '{name}' is required\")\n            if value is not None:\n                try:\n                    value = type_(value)  # Type coercion\n                except (ValueError, TypeError):\n                    raise ValueError(\n                        f\"Cannot convert {value!r} to {type_.__name__}\"\n                    )\n            setattr(self, name, value)\n\n    def __repr__(self):\n        fields = \", \".join(f\"{k}={getattr(self, k)!r}\" for k in self._fields)\n        return f\"{self.__class__.__name__}({fields})\"\n\n\nclass UserModel(PydanticLikeModel):\n    name: str\n    age: int\n    email: str\n\n\ndef demo_pydantic_models():\n    user = UserModel(name=\"Alice\", age=\"25\", email=\"alice@example.com\")\n    print(f\"  User: {user}\")\n    print(f\"  Age type: {type(user.age).__name__}\")  # int (coerced from str)\n\n    try:\n        UserModel(name=\"Bob\", age=\"not_a_number\", email=\"bob@example.com\")\n    except ValueError as e:\n        print(f\"  Validation error: {e}\")\n\n    print(\"\"\"\n  --- Real Pydantic v2 example (requires: pip install pydantic) ---\n  from pydantic import BaseModel, Field, field_validator\n\n  class User(BaseModel):\n      name: str = Field(min_length=1)\n      age: int = Field(ge=0, le=150)\n      email: str\n\n      @field_validator('email')\n      @classmethod\n      def validate_email(cls, v):\n          if '@' not in v:\n              raise ValueError('Invalid email')\n          return v\n\n  user = User(name=\"Alice\", age=25, email=\"alice@example.com\")\n  print(user.model_dump())        # {'name': 'Alice', 'age': 25, ...}\n  print(user.model_json_schema()) # JSON Schema\n  \"\"\")\n\n\nprint(\"Q204: Pydantic Models\")\ndemo_pydantic_models()\nprint()",
     "numbered": false
